import 'package:flutter/material.dart';import '../services/progress_store.dart';import '../widgets/ui.dart';
class SettingsScreen extends StatelessWidget{final ProgressStore store;const SettingsScreen({super.key,required this.store});@override Widget build(BuildContext c)=>AnimatedBuilder(animation:store,builder:(c,_)=>
 Scaffold(appBar:AppBar(title:const Text('SYSTEM SETTINGS')),body:ListView(padding:const EdgeInsets.all(22),children:[const NeonTitle('CONTROL DECK'),const SizedBox(height:20),SwitchListTile(tileColor:panel,title:const Text('Sound'),subtitle:const Text('Ready for game audio assets'),value:store.sound,onChanged:store.setSound),const SizedBox(height:10),SwitchListTile(tileColor:panel,title:const Text('Camera shake'),value:store.shake,onChanged:store.setShake),const SizedBox(height:10),const ListTile(tileColor:panel,leading:Icon(Icons.shield_outlined,color:cyan),title:Text('Privacy Policy')),const SizedBox(height:10),const ListTile(tileColor:panel,leading:Icon(Icons.description_outlined,color:cyan),title:Text('Terms & Conditions')),const SizedBox(height:20),ListTile(tileColor:panel,leading:const Icon(Icons.delete_forever,color:red),title:const Text('Reset all progress'),onTap:()=>reset(c))])));
